const filter = typeof filterName === 'string' ? filterName : 'iron_ore';
const found = drone.scanBlocks({ filter: filter, radius: 24 });
if (!found.count) return { ok: false, error: 'no ' + filter + ' within 24m', hint: 'move closer or scan a wider radius' };
let broken = 0;
for (var i = 0; i < found.blocks.length && i < 8; i++) {
  const b = found.blocks[i];
  const moved = drone.goto({ standoffOf: { x: b.x, y: b.y, z: b.z } });
  if (!moved.arrived) continue;
  const r = drone.breakBlock({ x: b.x, y: b.y, z: b.z });
  if (r.ok !== false && r.broken) broken++;
}
const p = drone.getPlayer();
const back = drone.goto({ x: p.blockX, y: p.blockY + 2, z: p.blockZ });
if (!back.arrived) return { ok: false, error: 'mined but could not return', broken: broken, position: drone.state() };
const given = drone.giveToPlayer({ filter: filter, count: 512 });
return { broken: broken, given: given };
